import {MUSIC_TRACKS} from './music-catalog.js';
export function createStoryMap(env){
 const {core:C,escape:esc,button:btn,icon:I,coin,sprite,heading,format:n,assetUrl,sceneAsset}=env;let selectedSeason=null,focusedChapter=null;
 const stagePoints=[[8,72],[25,53],[42,65],[59,37],[76,49],[92,22]];
 function currentSeason(){const state=env.getState(),list=C.seasons(state),last=C.mainChapters(state).at(-1)?.id||1,next=Math.min(state.story+1,last);return list.find(s=>s.id===selectedSeason)||list.find(s=>s.from<=next&&s.to>=next)||list[0];}
 function render(){const state=env.getState(),all=C.chapters(state),seasons=C.seasons(state),next=Math.min(state.story+1,C.mainChapters(state).at(-1).id);
  const season=currentSeason();
  const chapters=C.chaptersForSeason(state,season),completed=chapters.filter(c=>C.chapterComplete(state,c)).length,focus=chapters.find(c=>c.id===focusedChapter)||chapters.find(c=>c.id===next)||chapters[0],guide=state.catalog.find(r=>r.id===season.guideRobotId)||state.catalog[0];
  return `${heading('MODO HISTÓRIA',esc(state.settings.copy.storyTitle),esc(state.settings.copy.storyDescription))}<div class="campaign-overview"><span>${I('story')} ${seasons.length} temporadas</span><span>${I('arena')} ${all.length} capítulos</span><span>${I('gift')} ${state.story} concluídos</span>${state.activeStory&&!state.activeStory.settled&&state.activeStory.status!=='cancelled'?btn('Retomar expedição','resume-story','','secondary'):''}</div><div class="season-tabs" aria-label="Temporadas">${seasons.map((s,i)=>{const count=C.chaptersForSeason(state,s).filter(c=>C.chapterComplete(state,c)).length;return `<button data-a="season-select" data-id="${esc(s.id)}" class="season-card ${season.id===s.id?'selected':''} ${state.story<s.from-1?'locked-season':''}" style="--season-art:url('${assetUrl((s.sceneArt||sceneAsset(s.scene)))}')"><span>TEMPORADA ${String(i+1).padStart(2,'0')}</span><b>${esc(s.title)}</b><small>${count}/${C.chaptersForSeason(state,s).length} capítulos · ${state.story>=s.from-1?'Explorar':'A seguir'}</small></button>`;}).join('')}</div><section class="season-intro"><div class="guide-portrait"><img src="${assetUrl('nexa-guide.png')}" alt="NEXA, sua guia"></div><div><span class="eyebrow">${esc(state.settings.guideName||'NEXA')} · SEU GUIA</span><h2>${esc(season.subtitle)}</h2><p>${esc(season.intro)}</p><span class="season-music-label">${I('volume')} ${esc(MUSIC_TRACKS[season.musicTheme]?.name||'Trilha do universo')}</span></div></section><section class="story-season-map scene-${esc(season.scene)}" style="--season-art:url('${assetUrl((season.sceneArt||sceneAsset(season.scene)))}')"><div class="season-map-heading"><div><span class="eyebrow">ROTA DA TEMPORADA</span><h2>${esc(season.title)}</h2></div><div class="map-tools">${btn(I('chevron'),'map-pan','data-id="-1" aria-label="Explorar mapa à esquerda"','secondary')}${btn('Próximo sinal','map-next','','primary')}${btn(I('chevron'),'map-pan','data-id="1" aria-label="Explorar mapa à direita"','secondary')}<span>${completed}/${chapters.length} concluídos</span></div></div><div class="season-route-viewport"><div class="season-route" style="min-width:${Math.max(700,chapters.length*112)}px"><svg class="journey-line" viewBox="0 0 700 360" preserveAspectRatio="none" aria-hidden="true"><path d="${chapters.map((c,i)=>`${i?'L':'M'}${(8+i*84/Math.max(1,chapters.length-1))*7} ${stagePoints[i%6][1]*3.6}`).join(' ')}"/></svg>${chapters.map((c,i)=>{const point=[8+i*84/Math.max(1,chapters.length-1),stagePoints[i%6][1]],done=C.chapterComplete(state,c),current=C.chapterUnlocked(state,c)&&!done;return `<button class="journey-node ${done?'done':current?'current':'locked'} ${focus?.id===c.id?'focused':''}" data-a="map-focus" data-id="${c.id}" style="--x:${point[0]}%;--y:${point[1]}%" aria-label="Capítulo ${c.id}: ${esc(c.title)}"><span>${done?I('check'):String(c.id).padStart(2,'0')}</span>${current?`<img class="node-beacon" src="${assetUrl('map-beacon.png')}" alt="Próximo sinal"><em>PRÓXIMA MISSÃO</em>`:''}<b>${esc(c.title)}</b><small>${c.enemies?.length||0} encontros</small>${done?`<img class="node-chest claimed" src="${assetUrl('reward-chest.png')}" alt="Prêmio resgatado">`:''}</button>`;}).join('')}<div class="map-sparks">${Array.from({length:7},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div></div><div class="map-expedition-marker" aria-hidden="true">${sprite(guide)}</div><p class="map-hint">${I('story')} Siga os sinais luminosos. Cada capítulo abre o próximo caminho.</p></section>${focus?focusPanel(state,focus):''}<div class="story-how-to"><article><b>01</b><div><h3>Prepare sua equipe</h3><p>Escolha um robô ativo e alcance o poder indicado. Peças e níveis aumentam sua força.</p></div></article><article><b>02</b><div><h3>Explore e enfrente</h3><p>Acompanhe a viagem e os encontros. Use automático ou assuma ataque, defesa e especial.</p></div></article><article><b>03</b><div><h3>Abra o próximo sinal</h3><p>Vença todos os encontros para receber o prêmio único. Replays custam ${sReplay(state)} e não repetem o prêmio.</p></div></article></div><div class="section-title"><h2>Missões desta temporada</h2><span class="subtle">Capítulos ${season.from}–${season.to}</span></div><div class="chapter-list">${chapters.map(c=>{const done=C.chapterComplete(state,c),locked=!C.chapterUnlocked(state,c);return `<button class="chapter-card ${locked?'locked':''}" data-a="chapter" data-id="${c.id}"><span class="chapter-thumbnail"><img src="${assetUrl((c.sceneArt||C.seasonForChapter(state,c.id)?.sceneArt||sceneAsset(c.scene)))}" alt="${esc(c.place)}"><span class="chapter-number">${done?I('check'):String(c.id).padStart(2,'0')}</span></span><div><small>${esc(c.place)} · ${c.enemies?.length||0} encontros</small><h3>${esc(c.title)}</h3><p>${done?`Concluído · Replay ${c.replayCost??state.settings.replayCost} ${c.replayCurrency||state.settings.replayCurrency}`:locked?'Prepare-se para chegar a este setor':esc(c.objective||'Vença os guardiões e libere o sinal.')}</p></div><div class="chapter-reward">${coin('RC')} ${n(c.reward)}<small>${c.power} de poder</small></div>${I('chevron')}</button>`;}).join('')}</div>`;
 }
 function sReplay(state){return `${n(state.settings.replayCost)} ${state.settings.replayCurrency}`;}
 function focusPanel(state,c){const done=C.chapterComplete(state,c),locked=!C.chapterUnlocked(state,c),robot=state.robots.find(r=>r.uid===state.selectedRobot)||state.robots[0],power=robot?C.robotInfo(state,robot).power:0,enemies=C.storyEnemies(state,c.id),boss=enemies.at(-1);
  return `<section class="map-focus-panel" style="--focus-art:url('${assetUrl((c.sceneArt||C.seasonForChapter(state,c.id)?.sceneArt||sceneAsset(c.scene)))}')"><div class="focus-landscape"><span class="eyebrow">CAPÍTULO ${String(c.id).padStart(2,'0')} · ${esc(c.place)}</span><h2>${esc(c.title)}</h2><p>${esc(c.story)}</p></div><div class="focus-guardian">${sprite(boss.def)}<small>GUARDIÃO DO SETOR</small><b>${esc(boss.name)}</b></div><div class="focus-mission"><span class="eyebrow">${done?'EXPEDIÇÃO CONCLUÍDA':locked?'SINAL BLOQUEADO':'EXPEDIÇÃO DISPONÍVEL'}</span><div class="focus-prize"><img src="${assetUrl('reward-chest.png')}" alt="Baú da missão"><div>${coin('RC')}<b>${n(c.reward)} RC</b><small>${done?'Prêmio já resgatado':'Prêmio único ao concluir'}</small></div></div><div class="power-readiness"><span>Seu poder ${power} / ${c.power}</span><i><b style="width:${Math.min(100,power/c.power*100)}%"></b></i></div>${btn(locked?'Ver o setor':done?'Preparar replay':'Preparar expedição '+I('arrow'),'chapter',`data-id="${c.id}"`,locked?'secondary wide':'primary wide')}<small>${enemies.length} encontros · ${done?'Replay '+(c.replayCost??state.settings.replayCost)+' '+(c.replayCurrency||state.settings.replayCurrency):'Ataque, defesa e especial'}</small></div></section>`;
 }
 return {render,currentSeason,select:id=>{selectedSeason=id;focusedChapter=null;},focus:id=>{focusedChapter=id;const season=C.seasonForChapter(env.getState(),id);if(season)selectedSeason=season.id;}};
}
